  static String text(String languageCode, String key, [Map<String, String> values = const {}]) {
    final index = _keys.indexOf(key);
    final language = _values[languageCode] ?? _values['en']!;
    var result = index >= 0 && index < language.length
        ? language[index]
        : (index >= 0 ? _values['en']![index] : key);
    for (final entry in values.entries) {
      result = result.replaceAll('{${entry.key}}', entry.value);
    }
    return result;
  }
